        vm.createSelectFork("optimism", 156_364_034);

        exploit = new CozyFinanceExploit(ATTACKER);




        deal(address(USDC), address(exploit), 10_000e6);

        vm.label(ATTACKER, "Attacker");
        vm.label(address(exploit), "Exploit");
