            // Melt it for its ENJ backing (melt pays msg.sender == this contract).
            uint256[] memory oneId = new uint256[](1);
            uint256[] memory oneAmt = new uint256[](1);
            oneId[0] = id;
            oneAmt[0] = amts[i];
            PLATFORM.melt(oneId, oneAmt);
        }

        return IERC20(ENJ).balanceOf(address(this));
    }

