function trade(
        bool direction,
        uint256 size,
        uint256 minTradeReturn,
        uint256 initialGuess,
        address frontendAddress,
        uint8 leverage,
        bytes memory unverifiedReport
    )
        external
        nonReentrant
        returns (uint256)
    {
        IOracleMiddleware(oracle).verifyReportIfNecessary(unverifiedReport);
        require(leverage <= maxLeverage, "T0");

        address user = _msgSender();
        uint256 spotPrice = getPrice();

        require(
            direction ? size >= minimumTradeSize : (size * spotPrice) / oracleDecimals >= minimumTradeSize,
            "T2"
        );

        uint256 tradeReturn = 
            _trade(direction, size, minTradeReturn, initialGuess, frontendAddress, user, spotPrice);


        require(
            UtilMath.calcMR(user, spotPrice, address(this), getCollateral(user), lastOperationTimestamp) > MMR,
            "T1"
        );


        emit ExecutedTrade(
            user,
            direction,
            size,
            tradeReturn,
            spotPrice,
            leverage
        );

        return tradeReturn;
    }

function autoCloseUserPosition(address user, address frontendAddress, bytes memory unverifiedReport) external nonReentrant {
        IOracleMiddleware(oracle).verifyReportIfNecessary(unverifiedReport);
        require(autoCloseUsersData[user].authorized, "A1");
        (uint256 userPnL, bool userPnLSign) = calcPnL(user, getPrice());
        if (userPnLSign){
            require(autoCloseUsersData[user].profitTh != 0 && userPnL >= autoCloseUsersData[user].profitTh, "A1");
        }
        else{
            require(autoCloseUsersData[user].lossTh != 0 && userPnL >= autoCloseUsersData[user].lossTh && userPnL<=getCollateral(user), "A1");
        }
        userVirtualTraderPosition[user].debtStable += autoCloseFee;
        userVirtualTraderPosition[_msgSender()].balanceStable += autoCloseFee;
        _closeAndWithdraw(autoCloseUsersData[user].maxSlippage, autoCloseUsersData[user].maxLiqFee, frontendAddress, user);
        _disableAutoClose(user);
    }

function addLiquidity(uint256 liquidityStable, uint256 liquidityAsset, uint256 maxFeeValue, bytes memory unverifiedReport) public nonReentrant {
        IOracleMiddleware(oracle).verifyReportIfNecessary(unverifiedReport);
        address sender = _msgSender();
        uint256 spotPrice = getPrice();

        require(liquidityStable + (liquidityAsset * spotPrice) / oracleDecimals >= minimumLiquidityMovement, "L1"); 


        uint256 fee = FeeManager.computeLiquidityDepositFee(
            liquidityStable,
            liquidityAsset,
            globalLiquidityStable,
            globalLiquidityAsset,
            spotPrice,
            oracleDecimals,
            liquidityMaxFee,
            liquidityMinFee,
            liquidityFeeK,
            decimals.liquidityFeeDecimals
        );

        if (globalLiquidityAsset == 0 && globalLiquidityStable == 0) {
            fee = 0;
        }


        uint256 feeValue =
            ((liquidityStable + (liquidityAsset * spotPrice) / oracleDecimals) * fee) / decimals.liquidityFeeDecimals;

        require(feeValue <= maxFeeValue || maxFeeValue == 0, "L2");

        _addLiquidity(liquidityStable, liquidityAsset, feeValue, spotPrice);

        curveParameters.lastCurveUpdate = block.timestamp;
        curveParameters.lastValidatedPrice = spotPrice;
        dy0 = 0;
        dx0 = 0;

        LiquidityPosition storage position = liquidityPosition[sender];
        VirtualTraderPosition storage tpos = userVirtualTraderPosition[sender];

        uint256 collateral = getCollateral(sender);
        (uint256 pnl, bool pnlSign) = calcPnL(sender, spotPrice);
        require(pnl<collateral || pnlSign, "C1");  

        require(position.debtStable + tpos.debtStable + (position.debtAsset + tpos.debtAsset)*spotPrice/oracleDecimals <= collateral*maxLpLeverage, "L3"); 
    }

function closeAndWithdraw(uint256 maxSlippage, uint256 maxLiqFee, address frontendAddress, bytes memory unverifiedReport) public nonReentrant {
        address user = _msgSender();
        IOracleMiddleware(oracle).verifyReportIfNecessary(unverifiedReport);
        _closeAndWithdraw(maxSlippage, maxLiqFee, frontendAddress, user);   
    }

function removeLiquidity(
        uint256 liquidityStableToRemove,
        uint256 liquidityAssetToRemove,
        uint256 maxFeeValue,
        bytes memory unverifiedReport
    )
        external
        nonReentrant
    {
        IOracleMiddleware(oracle).verifyReportIfNecessary(unverifiedReport);
        uint256 spotPrice = getPrice();

        require(
            liquidityStableToRemove + (liquidityAssetToRemove * spotPrice) / oracleDecimals >= minimumLiquidityMovement,
        "L4"
        ); 

        address sender = _msgSender();
        _removeLiquidity(liquidityStableToRemove, liquidityAssetToRemove, sender, spotPrice, maxFeeValue);

        (uint256 pnl, bool pnlSign) = calcPnL(sender, spotPrice);
        require(pnl<getCollateral(sender) || pnlSign, "C1");  

    }

function realizePnL(bytes memory unverifiedReport) external nonReentrant returns(uint256, bool){
        IOracleMiddleware(oracle).verifyReportIfNecessary(unverifiedReport);
        address user = _msgSender();
        VirtualTraderPosition storage pos = userVirtualTraderPosition[user];
        (uint256 pnl, bool pnlSign) = calcPnL(user, getPrice());
        require(pnlSign || pnl<getCollateral(user), "R1");
        if (!pnlSign){
            if (pnl<pos.debtStable){
                pos.debtStable -= pnl;
            } else {
                pos.balanceStable += (pnl - pos.debtStable);
                pos.debtStable = 0;
            }
        } else {
            if (pnl<pos.balanceStable){
                pos.balanceStable -= pnl;
            } else {
                pos.debtStable += (pnl - pos.balanceStable);
                pos.balanceStable = 0;
            }
        }
        IVault(vault).addPnlToCollateral(user, pnl, pnlSign);
        emit RealizedPnL(user, pnl, pnlSign);
        return (pnl, pnlSign);
    }

function updateFG(bytes memory unverifiedReport) external {
        IOracleMiddleware(oracle).verifyReportIfNecessary(unverifiedReport);
        _updateFG(getPrice(), lastOperationTimestamp);
        lastOperationTimestamp = block.timestamp;
    }

function enableAutoClose(uint256 profitTh, uint256 lossTh, uint256 maxSlippage, uint256 maxLiqFee) external {
        require(profitTh > 0 || lossTh > 0, "A");
        address user = _msgSender();
        autoCloseUsersData[user].authorized = true;
        autoCloseUsersData[user].profitTh = profitTh;
        autoCloseUsersData[user].lossTh = lossTh;
        autoCloseUsersData[user].maxSlippage = maxSlippage;
        autoCloseUsersData[user].maxLiqFee = maxLiqFee;
        emit EnabledAutoClose(user, profitTh, lossTh);
    }

function setTimeLockedParameters(
        uint256 _MMR,
        uint256 _tradingFee,
        uint256 _flatTradingFee,
        uint256 _feeLP,
        uint256 _liquidityMinFee,
        uint256 _liquidityMaxFee,
        uint256 _liquidityFeeK,
        uint256 _fundingC,
        UtilMath.ClampParameters memory _clampParams,
        uint256 _paramTimeLock,
        uint256 _minimumTradeSize
    )
    external
    onlyRole(MOD_ROLE)
    {
        bytes32 newParamHash = keccak256(
            abi.encode(
                keccak256(
                    abi.encodePacked(
                    _MMR, 
                    _tradingFee, 
                    _flatTradingFee, 
                    _feeLP)
                ),
                _liquidityMinFee,
                _liquidityMaxFee,
                _liquidityFeeK,
                _fundingC,
                _clampParams,
                _paramTimeLock,
                _minimumTradeSize
        ));
        require(block.timestamp >= paramLockedUntil && newParamHash == paramHash, "C");


        MMR = _MMR;
        feeLP = _feeLP;
        flatTradingFee = _flatTradingFee;
        tradingFee = _tradingFee;
        liquidityMinFee = _liquidityMinFee;
        liquidityMaxFee = _liquidityMaxFee;
        liquidityFeeK = _liquidityFeeK;
        fundingC = _fundingC;
        clampParameters = _clampParams;
        paramTimeLock = _paramTimeLock;
        minimumTradeSize = _minimumTradeSize;
    }

function _trade(
        bool direction,
        uint256 size,
        uint256 minTradeReturn,
        uint256 initialGuess,
        address frontendAddress,
        address user,
        uint256 spotPrice
    )
        internal
        returns (uint256)
    {

        uint256 stableLiq = globalLiquidityStable;
        uint256 assetLiq = globalLiquidityAsset;
        uint256 tradingFeeAmount;
        uint256 tradeReturn;
        uint256 shortTotalTradeReturn;

        uint256 _oracleDecimals = oracleDecimals;
        uint256 _feeFrontend = feeFrontend;
        uint256 _lastOperationTimestamp = lastOperationTimestamp;

        uint256 zeroSlippageReturn = direction ? size * _oracleDecimals / spotPrice : size * spotPrice / _oracleDecimals;

        if(
           block.timestamp > curveParameters.lastCurveUpdate + curveParameters.curveUpdateInterval ||
           curveParameters.lastTradeDirection != direction ||
           curveParameters.lastValidatedPrice != spotPrice
           )
        {
            curveParameters.lastCurveUpdate = block.timestamp;
            curveParameters.lastTradeDirection = direction;
            curveParameters.lastValidatedPrice = spotPrice;
            delete dy0;
            delete dx0;
        }


        if (direction) {
            if (assetLiq <= zeroSlippageReturn) {
                initialGuess = 0;
            }
            else if(initialGuess > assetLiq || initialGuess < (assetLiq - zeroSlippageReturn)){
                initialGuess = assetLiq - zeroSlippageReturn;
            }

            tradingFeeAmount = (size * tradingFee) / decimals.tradingFeeDecimals + flatTradingFee;
            if(size > tradingFeeAmount){

                uint256 frontendFeePart = (tradingFeeAmount * _feeFrontend) / decimals.feeFractionsDecimals;
                if(frontendAddress==address(0)){
                    tradeReturn = CurveMath.computeLongReturn(
                        size - (tradingFeeAmount - frontendFeePart) + dy0,
                        spotPrice,
                        _oracleDecimals,
                        initialGuess,
                        stableLiq - dy0,
                        assetLiq + dx0,
                        curveParameters.longCurveParameterA,
                        curveParameters.longCurveParameterB,
                        1e8
                    ) - dx0;
                    dy0 += size - (tradingFeeAmount - frontendFeePart);
                }
                else{
                    tradeReturn = CurveMath.computeLongReturn(
