struct Position {
    address user;
    uint256 x;
    uint256 y;
    uint256 debt;
    int256 health;
}

interface IcrvController {
    function create_loan(
        uint256 collateral,
        uint256 debt,
        uint256 nBands
    ) external payable;

    function users_to_liquidate() external returns (Position[] memory);

    function liquidate(
        address user,
        uint256 min_x
    ) external;

    function min_collateral(
        uint256 debt,
        uint256 nBands
    ) external returns (uint256);

    function repay(
        uint256 d_debt
    ) external;
}

interface IcurveStableSwap {
    function exchange(
        int128 i,
        int128 j,
        uint256 dx,
        uint256 min_dy
    ) external;

    function exchange_underlying(
        int128 i,
        int128 j,
        uint256 dx,
        uint256 min_dy
    ) external;

    function get_dx(
        int128 i,
        int128 j,
        uint256 dy
    ) external returns (uint256);
}

interface IYearnV3Vault {
    function deposit(
        uint256 assets,
        address receiver
    ) external;

    function approve(
        address spender,
        uint256 amount
    ) external;

    function balanceOf(
        address account
    ) external returns (uint256);

    function redeem(
        uint256 shares,
        address receiver,
        address owner
    ) external;
}

interface ILLAMMAExchange {
    function exchange(
        uint256 i,
        uint256 j,
        uint256 in_amount,
        uint256 min_amount
    ) external returns (uint256[2] memory);
}

interface IDolaSavings {
    function stake(
        uint256 amount,
        address recipient
    ) external;
}

