    address internal constant ATTACKER = 0xB3764761E297D6f121e79C32A65829Cd1dDb4D32;
    IParityWallet internal constant VICTIM_WALLET = IParityWallet(0xBEc591De75b8699A3Ba52F073428822d0Bfc0D7e);
