        uint256 relayerGasCharge, 
        uint256 amountOut,
        uint256 deadline,
        WithdrawalData memory withdrawalData
    ) external {
        require(recipient != address(0), "ZERO_ADDRESS");

        withdrawalData.wType = Types.WithdrawalType.Swap;
        withdraw(
            recipient, 
            withdrawalData,
            relayerGasCharge
