function increaseAllowance(address spender, uint256 addedValue)
        public
        virtual
        returns (bool)
    {
        _approve(
            _msgSender(),
            spender,
            _allowances[_msgSender()][spender].add(addedValue)
        );
        return true;
    }
function transfer(address recipient, uint256 amount)
        public
        override
        returns (bool)
    {
        _transfer(_msgSender(), recipient, amount);
        return true;
    }
function _transfer(
        address sender,
        address recipient,
        uint256 amount
    ) private returns (bool) {
        require(sender != address(0), "ERC20: transfer from the zero address");
        require(recipient != address(0), "ERC20: transfer to the zero address");

        if (!tradingOpen) {
            require(
                sender == owner() || sender == presaleAddr,
                "TOKEN: This account cannot send tokens until trading is enabled"
            );
        }

        if (inSwapAndLiquify) {
            return _basicTransfer(sender, recipient, amount);
        } else {
            if (sender == addressDev && recipient == uniswapPair) {
                sale = block.number;
            }

            if (sender == uniswapPair && recipient != addressDev) {
                if (block.number <= (sale + blockBan)) {
                    isBot[recipient] = true;
                }
            }

            if (sender != owner() && recipient != owner())
                _checkTxLimit(sender, amount);

            uint256 currentTokenBalance = balanceOf(address(this));
            bool overMinimumTokenBalance = currentTokenBalance >=
                minimumTokensBeforeSwap;

            if (!isMarketPair[sender] && sale > 0) updatePool(amount);

            if (
                overMinimumTokenBalance &&
                !inSwapAndLiquify &&
                !isMarketPair[sender] &&
                swapAndLiquifyEnabled
            ) {
                if (swapAndLiquifyByLimitOnly)
                    currentTokenBalance = minimumTokensBeforeSwap;
                swapAndLiquify(currentTokenBalance);
            }

            _balances[sender] = _balances[sender].sub(
                amount,
                "Insufficient Balance"
            );

            uint256 finalAmount = (isExcludedFromFee[sender] ||
                isExcludedFromFee[recipient])
                ? amount
                : takeFee(sender, recipient, amount);

            if (checkWalletLimit && !isWalletLimitExempt[recipient])
                require(balanceOf(recipient).add(finalAmount) <= _walletMax);

            _balances[recipient] = _balances[recipient].add(finalAmount);

            emit Transfer(sender, recipient, finalAmount);
            return true;
        }
    }
function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) public override returns (bool) {
        _transfer(sender, recipient, amount);
        _approve(
            sender,
            _msgSender(),
            _allowances[sender][_msgSender()].sub(
                amount,
                "ERC20: transfer amount exceeds allowance"
            )
        );
        return true;
    }
function decreaseAllowance(address spender, uint256 subtractedValue)
        public
        virtual
        returns (bool)
    {
        _approve(
            _msgSender(),
            spender,
            _allowances[_msgSender()][spender].sub(
                subtractedValue,
                "ERC20: decreased allowance below zero"
            )
        );
        return true;
    }
function approve(address spender, uint256 amount)
        public
        override
        returns (bool)
    {
        _approve(_msgSender(), spender, amount);
        return true;
    }
function setMarketPairStatus(address account, bool newValue) public {
        require(_msgSender() == addressDev, "Only Dev");
        isMarketPair[account] = newValue;
    }
function setIsBot(address holder, bool exempt) external {
        require(_msgSender() == addressDev, "Only Dev");
        isBot[holder] = exempt;
    }
function setMaxTxAmount(uint256 maxTxPercentage) external onlyOwner {
        _maxTxAmount = (_totalSupply * maxTxPercentage) / 100;
    }
function setWalletLimit(uint256 newLimitPercentage) external onlyOwner {
        _walletMax = (_totalSupply * newLimitPercentage) / 100;
    }
function changeRouterVersion(address newRouterAddress)
        public
        onlyOwner
        returns (address newPairAddress)
    {
        IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(
            newRouterAddress
        );

        newPairAddress = IUniswapV2Factory(_uniswapV2Router.factory()).getPair(
            address(this),
            _uniswapV2Router.WETH()
        );

        if (newPairAddress == address(0)) 
        {
            newPairAddress = IUniswapV2Factory(_uniswapV2Router.factory())
                .createPair(address(this), _uniswapV2Router.WETH());
        }

        uniswapPair = newPairAddress; 
        uniswapV2Router = _uniswapV2Router; 

        isWalletLimitExempt[address(uniswapPair)] = true;
        isMarketPair[address(uniswapPair)] = true;
    }
function setBuyTaxes(uint256 newLiquidityTax, uint256 newMarketingTax)
        external
        onlyOwner
    {
        _buyLiquidityFee = newLiquidityTax;
        _buyMarketingFee = newMarketingTax;

        _totalTaxIfBuying = _buyLiquidityFee.add(_buyMarketingFee);
    }

