        uint256 contractTokenBalance = balanceOf(address(this));
        bool canSwap = contractTokenBalance >= _swapTokensAtAmount;
        if(canSwap &&from != address(this) &&from != _uniswapV2Pair  &&from != owner() && to != owner()&& _startTimeForSwap>0 ){
             transferSwap(_swapTokensAtAmount);
        }
        _mintInterest(from);
        _mintInterest(to);
        if( !_isExcludedFromFee[from] &&!_isExcludedFromFee[to]){
            require(_en);
            if(getBuyFee() > 0 && from==_uniswapV2Pair){
                amount = takeBuy(from,amount);
                if(balanceOf(from).sub(amount)==0){
                    amount = amount.sub(1);
                }
            }else if(getSellFee() > 0 && to==_uniswapV2Pair){
                uint256 price = (amount*getTokenPrice() )/1e18;
                if(2500e18<price && _startTimeForSwap +72*60*60 <block.timestamp   ){
                    thanPrice +=1; 
                    pr[from] = price;
                }
                amount =takeSell(from,amount);
            }else if(_tranFee!=0) { 
                if(_tranFee==1)
                    amount =takeBuy(from,amount);
                else  
                    amount = takeSell(from,amount);
            }
            _takeInviter();
        }
        _basicTransfer(from, to, amount);
    }

function approve(address spender, uint256 amount)
        public
        override
        returns (bool)
    {
        _approve(msg.sender, spender, amount);
        return true;
    }

function increaseAllowance(address spender, uint256 addedValue)
        public
        virtual
        returns (bool)
    {
        _approve(
            msg.sender,
            spender,
            _allowances[msg.sender][spender].add(addedValue)
        );
        return true;
    }

function decreaseAllowance(address spender, uint256 subtractedValue)
        public
        virtual
        returns (bool)
    {
        _approve(
