                poolId: poolId,
                assetInIndex: 0,
                assetOutIndex: 1,
                amount: amount,
                userData: bytes("")
            });
            amount = amount * 1e3;
            buffer[stepCount++] = IBalancerVault.BatchSwapStep({
                poolId: poolId,
                assetInIndex: 2,
                assetOutIndex: 1,
                amount: amount,
                userData: bytes("")
            });
            amount = amount * 1e3;
        }

        buffer[stepCount++] = IBalancerVault.BatchSwapStep({
            poolId: poolId,
            assetInIndex: 0,
            assetOutIndex: 1,
            amount: amount,
