function getTokenAmountFromUSDT(uint256 usdtAmount)
        public
        view
        returns (uint256)
    {
        IPancakeRouter pancakeRouter = IPancakeRouter(router); 

        address bnbAddress = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; 
        address usdtAddress = 0x55d398326f99059fF775485246999027B3197955; 
        uint256 value1 = quoteUSDTFactor;


        address[] memory path = new address[](3);
        path[0] = usdtAddress;
        path[1] = bnbAddress;
        path[2] = tokenAddress;


        uint256[] memory amounts = pancakeRouter.getAmountsOut(value1, path);
        uint256 AmountValue = (amounts[2] * usdtAmount) / quoteUSDTFactor;

        return AmountValue;
    }

